use std::fmt;
#[derive(Clone, Debug, PartialEq)]
pub struct LexError { pub offset: usize, pub message: String }
impl fmt::Display for LexError { fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{} at byte {}",self.message,self.offset)} }
impl std::error::Error for LexError {}
#[derive(Clone, Debug, PartialEq)]
pub enum TokenKind { Number(f64), String(String), Identifier(String), Let, Const, Function, Return, Typeof, Void, Delete, If, Else, Do, While, For, Switch, Case, Default, Break, Continue, True, False, Null, Undefined, Plus, PlusEqual, PlusPlus, Minus, MinusEqual, MinusMinus, Star, StarEqual, Slash, SlashEqual, Percent, PercentEqual, Power, Bang, Equal, EqualEqual, StrictEqual, BangEqual, StrictBangEqual, Less, LessEqual, Greater, GreaterEqual, AndAnd, OrOr, Nullish, Arrow, Ellipsis, In, LeftParen, RightParen, LeftBrace, RightBrace, LeftBracket, RightBracket, Dot, Colon, Question, Semicolon, Comma, Eof }
#[derive(Clone, Debug, PartialEq)]
pub struct Token { pub kind: TokenKind, pub offset: usize }
pub fn tokenize(source:&str)->Result<Vec<Token>,LexError>{
 let bytes=source.as_bytes();let mut tokens=Vec::new();let mut i=0;
 while i<bytes.len(){let b=bytes[i];if b.is_ascii_whitespace(){i+=1;continue}
 if b==b'/'&&bytes.get(i+1)==Some(&b'/'){i+=2;while i<bytes.len()&&bytes[i]!=b'\n'{i+=1}continue}
 if b==b'/'&&bytes.get(i+1)==Some(&b'*'){let s=i;i+=2;while i+1<bytes.len()&&!(bytes[i]==b'*'&&bytes[i+1]==b'/'){i+=1}if i+1>=bytes.len(){return Err(LexError{offset:s,message:"unterminated block comment".into()})}i+=2;continue}
 let start=i;let kind=if b.is_ascii_digit()||(b==b'.'&&bytes.get(i+1).is_some_and(u8::is_ascii_digit)){let number=if b==b'0'&&matches!(bytes.get(i+1),Some(&b'x'|&b'X'|&b'b'|&b'B'|&b'o'|&b'O')){let base=match bytes[i+1]{b'x'|b'X'=>16,b'b'|b'B'=>2,_=>8};i+=2;let digits=i;while i<bytes.len()&&bytes[i].is_ascii_hexdigit()&&char::from(bytes[i]).to_digit(base).is_some(){i+=1}if digits==i{return Err(LexError{offset:start,message:"expected digits after numeric prefix".into()})}u64::from_str_radix(&source[digits..i],base).map(|n|n as f64).map_err(|_|LexError{offset:start,message:"numeric literal out of range".into()})?}else{if b==b'.'{i+=1;while i<bytes.len()&&bytes[i].is_ascii_digit(){i+=1}}else{while i<bytes.len()&&bytes[i].is_ascii_digit(){i+=1}if i<bytes.len()&&bytes[i]==b'.'{i+=1;while i<bytes.len()&&bytes[i].is_ascii_digit(){i+=1}}}if i<bytes.len()&&matches!(bytes[i],b'e'|b'E'){i+=1;if i<bytes.len()&&matches!(bytes[i],b'+'|b'-'){i+=1}let exp=i;while i<bytes.len()&&bytes[i].is_ascii_digit(){i+=1}if exp==i{return Err(LexError{offset:start,message:"invalid numeric exponent".into()})}}let raw=&source[start..i];raw.parse::<f64>().map_err(|_|LexError{offset:start,message:format!("invalid number '{raw}'")})?};TokenKind::Number(number)}
 else if b==b'\''||b==b'"'||b==b'`'{let q=b;i+=1;let mut s=String::new();while i<bytes.len()&&bytes[i]!=q{if bytes[i]==b'\\'{i+=1;if i>=bytes.len(){break}match bytes[i]{b'n'=>{s.push('\n');i+=1},b'r'=>{s.push('\r');i+=1},b't'=>{s.push('\t');i+=1},b'b'=>{s.push('\u{0008}');i+=1},b'f'=>{s.push('\u{000c}');i+=1},b'v'=>{s.push('\u{000b}');i+=1},b'0'=>{s.push('\0');i+=1},b'\n'=>{i+=1},b'x'|b'u'=>{let marker=bytes[i];let count=if marker==b'x'{2}else{4};i+=1;if i+count>bytes.len(){return Err(LexError{offset:start,message:"short hexadecimal escape".into()})}let hex=&source[i..i+count];let code=u32::from_str_radix(hex,16).map_err(|_|LexError{offset:start,message:"invalid hexadecimal escape".into()})?;let ch=char::from_u32(code).ok_or_else(||LexError{offset:start,message:"invalid Unicode escape".into()})?;s.push(ch);i+=count},other if other.is_ascii()=>{s.push(other as char);i+=1},_=>{let c=source[i..].chars().next().unwrap();s.push(c);i+=c.len_utf8()}}}else{let c=source[i..].chars().next().unwrap();s.push(c);i+=c.len_utf8()}}if i>=bytes.len(){return Err(LexError{offset:start,message:"unterminated string".into()})}i+=1;TokenKind::String(s)}
 else if b.is_ascii_alphabetic()||b==b'_'||b==b'$'{i+=1;while i<bytes.len()&&(bytes[i].is_ascii_alphanumeric()||bytes[i]==b'_'||bytes[i]==b'$'){i+=1}match &source[start..i]{"let"=>TokenKind::Let,"const"=>TokenKind::Const,"function"=>TokenKind::Function,"return"=>TokenKind::Return,"typeof"=>TokenKind::Typeof,"delete"=>TokenKind::Delete,"void"=>TokenKind::Void,"if"=>TokenKind::If,"else"=>TokenKind::Else,"in"=>TokenKind::In,"do"=>TokenKind::Do,"while"=>TokenKind::While,"for"=>TokenKind::For,"switch"=>TokenKind::Switch,"case"=>TokenKind::Case,"default"=>TokenKind::Default,"break"=>TokenKind::Break,"continue"=>TokenKind::Continue,"true"=>TokenKind::True,"false"=>TokenKind::False,"null"=>TokenKind::Null,"undefined"=>TokenKind::Undefined,n=>TokenKind::Identifier(n.into())}}
 else{let r=&source[i..];let(k,w)=if r.starts_with("!=="){(TokenKind::StrictBangEqual,3)}else if r.starts_with("+="){(TokenKind::PlusEqual,2)}else if r.starts_with("-="){(TokenKind::MinusEqual,2)}else if r.starts_with("*="){(TokenKind::StarEqual,2)}else if r.starts_with("/="){(TokenKind::SlashEqual,2)}else if r.starts_with("%="){(TokenKind::PercentEqual,2)}else if r.starts_with("++"){(TokenKind::PlusPlus,2)}else if r.starts_with("--"){(TokenKind::MinusMinus,2)}else if r.starts_with("==="){(TokenKind::StrictEqual,3)}else if r.starts_with("**"){(TokenKind::Power,2)}else if r.starts_with("=="){(TokenKind::EqualEqual,2)}else if r.starts_with("!="){(TokenKind::BangEqual,2)}else if r.starts_with("<="){(TokenKind::LessEqual,2)}else if r.starts_with(">="){(TokenKind::GreaterEqual,2)}else if r.starts_with("&&"){(TokenKind::AndAnd,2)}else if r.starts_with("||"){(TokenKind::OrOr,2)}else if r.starts_with("??"){(TokenKind::Nullish,2)}else if r.starts_with("..."){(TokenKind::Ellipsis,3)}else if r.starts_with("=>"){(TokenKind::Arrow,2)}else{(match b{b'+'=>TokenKind::Plus,b'-'=>TokenKind::Minus,b'*'=>TokenKind::Star,b'/'=>TokenKind::Slash,b'%'=>TokenKind::Percent,b'!'=>TokenKind::Bang,b'='=>TokenKind::Equal,b'<'=>TokenKind::Less,b'>'=>TokenKind::Greater,b'('=>TokenKind::LeftParen,b')'=>TokenKind::RightParen,b'{'=>TokenKind::LeftBrace,b'}'=>TokenKind::RightBrace,b'['=>TokenKind::LeftBracket,b']'=>TokenKind::RightBracket,b'.'=>TokenKind::Dot,b':'=>TokenKind::Colon,b'?'=>TokenKind::Question,b';'=>TokenKind::Semicolon,b','=>TokenKind::Comma,_=>return Err(LexError{offset:i,message:format!("unexpected character '{}'",b as char)})},1)};i+=w;k};
 tokens.push(Token{kind,offset:start});}
 tokens.push(Token{kind:TokenKind::Eof,offset:source.len()});Ok(tokens)
}
#[cfg(test)]mod tests{use super::*;#[test]fn keywords(){let t=tokenize("if (x) {}").unwrap();assert_eq!(t[0].kind,TokenKind::If);assert_eq!(t[3].kind,TokenKind::LeftBrace)}#[test]fn numeric_literals(){let t=tokenize("0xff 0b101 0o17 1.25 2e3 4.5e-2").unwrap();let values:Vec<f64>=t.into_iter().filter_map(|x|if let TokenKind::Number(n)=x.kind{Some(n)}else{None}).collect();assert_eq!(values,vec![255.0,5.0,15.0,1.25,2000.0,0.045]);}#[test]fn invalid_numeric_literals(){assert!(tokenize("0x").is_err());assert!(tokenize("1e+").is_err());}#[test]fn string_escape_sequences(){let t=tokenize(r#""a\nb\x41\u263A\0""#).unwrap();assert_eq!(t[0].kind,TokenKind::String("a\nbA☺\0".into()));}#[test]fn bad_string(){assert!(tokenize("'oops").is_err())}}